package com.johnny.hotel.cashier;import com.johnny.hotel.cashier.CashierModels.*;import com.johnny.hotel.common.Result;import com.johnny.hotel.pagination.PageResult;import jakarta.validation.Valid;import lombok.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/cashier")@RequiredArgsConstructor@PreAuthorize("hasAnyRole('STAFF','MANAGER','FINANCE','OWNER','SUPER_ADMIN')")public class CashierController{private final CashierService service;@PostMapping("/drawers")@PreAuthorize("hasAnyRole('FINANCE','OWNER','SUPER_ADMIN')")public Result<Drawer>drawer(@Valid@RequestBody CreateDrawer r){return Result.success(service.createDrawer(r));}@PostMapping("/drawers/{id}/shifts")public Result<ShiftView>open(@PathVariable Long id,@Valid@RequestBody Count c){return Result.success(service.open(id,c));}@PostMapping("/shifts/{id}/count")public Result<ShiftView>count(@PathVariable Long id,@Valid@RequestBody Count c){return Result.success(service.countClose(id,c));}@PostMapping("/shifts/{id}/close")public Result<ShiftView>close(@PathVariable Long id,@Valid@RequestBody Count c){return Result.success(service.close(id,c));}@PostMapping("/variances/{id}/review")@PreAuthorize("hasAnyRole('MANAGER','OWNER','SUPER_ADMIN')")public Result<Variance>review(@PathVariable Long id,@RequestBody(required=false)String note){return Result.success(service.reviewVariance(id,note));}@GetMapping("/shifts/{id}")public Result<ShiftView>get(@PathVariable Long id){return Result.success(service.get(id));}@GetMapping("/shifts")public Result<PageResult<Shift>>history(@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer pageSize){return Result.success(service.history(page,pageSize));}@PostMapping("/shifts/{id}/cash-transfers")public Result<Transfer>request(@PathVariable Long id,@Valid@RequestBody TransferRequest r){return Result.success(service.requestTransfer(id,r));}@PostMapping("/cash-transfers/{id}/confirm")@PreAuthorize("hasAnyRole('FINANCE','OWNER','SUPER_ADMIN')")public Result<Transfer>confirm(@PathVariable Long id){return Result.success(service.confirmTransfer(id));}@PostMapping("/cash-transfers/{id}/cancel")public Result<Transfer>cancel(@PathVariable Long id){return Result.success(service.cancelTransfer(id));}}
